function filter$analysisSalesData(p){
  this.constructor(p);
}
filter$analysisSalesData.prototype = new DirEvent();
filter$analysisSalesData.prototype.afterInit = function(){
  var p = this._dir;

  p.find('.btn_add_rows, .btn_remove_rows, .btn_moveup_rows, .btn_movedown_rows').html("<div></div>");
  p.find('.btn_remove_rows').insertAfter(p.find('.btn_add_rows'));
  p.find('.btn_moveup_rows').insertAfter(p.find('.btn_remove_rows'));
  p.find('.btn_movedown_rows').insertAfter(p.find('.btn_moveup_rows'));

  p.find('.data_struct_label, .data_rows_label, .data_columns_label, .data_pivot_label').prepend("<div></div>");
  p.find('.data_struct_label').insertBefore(p.find('.data_struct'));
  p.find('.data_rows_label').insertBefore(p.find('.data_rows'));
  p.find('.data_columns_label').insertBefore(p.find('.data_columns'));
  p.find('.data_pivot_label').insertBefore(p.find('.data_pivot'));

  p.options.pivotGroupAvailable = 1
  p.options.dataChanged = true;
  p.setHidden('form_type', (p.options._admin == 0));
  p.options.pivotGroups = [];
  p.request('GetRight', 'GetTable', null, filter$analysisInitAllField);
  //filter$analysisInitAllField(p);
}
filter$analysisSalesData.prototype.beforeButtonDialogClick = function (id) {
  var p = this._dir;

  if(id == "zoom"){
    var dstr = p.find('.data_struct');
    var drow = p.find('.data_rows');
    if (p.options.fullScreen){
      dstr.css("min-height", "0px");
      drow.css("min-height", "0px");
    }
    else{
      var modal = p.find('.modal-dialog');
      var hx =  $(document).height() - modal.height();
      dstr.css("min-height", dstr.outerHeight() + hx + "px");
      drow.css("min-height", drow.outerHeight() + hx + "px");
    }
  }

  return true;
}
filter$analysisSalesData.prototype.beforeAcceptFilter = function (m2, opt, sub) {
  var p = this._dir, pid = "0", v = filter$analysisGetPivotValue(p, pid);
  if (v == "") return;
  opt._data_analysis_struct_df = p.valForm('data_analysis_struct');
  opt._data_analysis_struct = v;
  m2.val('data_analysis_struct', 'C', v);
  return [m2, opt, sub];
}
filter$analysisSalesData.prototype.commandActionClick = function (action, id) {
  var p = this._dir, lst = p.jObject('data_struct').list('instance'), lstRows = p.jObject('data_rows').list('instance'), lstColumns = p.jObject('data_columns').list('instance'), lstPivot = p.jObject('data_pivot').list('instance'), a = lst.val(), k = a.length;
  switch (action) {
    case "btn_add_rows":
      var jos = filter$analysis$TransferColumns(p, lst, lstRows, false);
      filter$analysis$MenuTextInRow(p, jos);
      break;
    case "btn_remove_rows":
      filter$analysisInitRestoreToStruct(p, lstRows.selectedItems());
      filter$analysis$RefreshGroupInRow(p);
      break;
    case "btn_moveup_rows":
      filter$analysis$MoveUp(p.options.listFocus);
      break;
    case "btn_movedown_rows":
      filter$analysis$MoveDown(p.options.listFocus);
      break;
    case "btn_deleteall_rows":
      filter$analysisInitRestoreToStruct(p, lstRows.jItems())
      p.options.pivotGroups = [];
      break;
    case "btn_deleteall_columns":
      filter$analysisInitRestoreToStruct(p, lstColumns.jItems())
      break;
    case "btn_deleteall_pivots":
      filter$analysisInitRestoreToStruct(p, lstPivot.jItems())
      break;
    case "btn_save_new":
      var v = filter$analysisGetPivotValue(p, "");
      if (v == "") return;
      if (p.tabActive() != "2") {
        p.tabActive("2");
        p.valForm('form_type', 0);
        p.jObject('form_type').focus(); 
      }
      p.showFilter('messageInput', null, {title: p.msg('inputNewName'), label: p.msg('formName'), allowBlank: false, msgFunction: function (q, ok, ctext) {
          q._close();
          if (ok){
            p.options._filterAction = 'NEW';
            p.valForm('name', ctext);
            p.request(p.options._filterAction, '', [['name', 'C', ctext], 'name2', 'form_type', ['controller', 'C', p.options.controller], ['reportForm', 'C', v]], function(pp, d, run){
              if (run) {
                $.clearClientCache();
                $.showToast('$Processed', p);
              }
            });
          }
        }});

      break;
    case "btn_save_overwrite":
      if (p.valForm('data_analysis_struct') == "") {
        p.jObject('data_analysis_struct').focus(); 
        return;
      }
      var v = filter$analysisGetPivotValue(p, p.options._pivotInfo.split('|')[0]);
      if (v == "") return;
      if (p.valForm('name') == '') {
        p.tabActive("2");
        p.jObject('name').focus(); 
        return false;
      }
      p.options._filterAction = 'EDIT';
      p.request(p.options._filterAction, '', ['name', 'name2', 'form_type', ['controller', 'C', p.options.controller], ['reportForm', 'C', v], ['id', 'C', p.valForm('data_analysis_struct')]], function(pp, d, run){
        if (run) {
          $.clearClientCache();
          $.showToast('$Processed', p);
        }
      });
      break;
    case 'btn_delete_form':
      if (p.valForm('data_analysis_struct') == "") {
        p.jObject('data_analysis_struct').focus(); 
        return;
      }
      $.question($.msg.get("VoucherDelete"), $.msg.get("DeleteTitle"), p, function (q, v) {
          if (v) {
            var m = new Memvars(), o = p.jObject('data_analysis_struct'), v = o.fval(), time = $.userinfo.val('CommandTimeout');
            m.add([['id', 'C', v], ['controller', 'C', p.options.controller]]);
            var param = { strCommand: "Filter-deletePivotForm-GetRow", oMemvar: m.val() };
            p.wait(true, action);
            $.invoke('RunSQL', param, p, time, function (d) {
                var run = p.runDataReturn(d);
                if (run) {
                    o.find("[value='" + o.fval() + "']").remove();
                    o.fval("");
                    o.focus();
                    p.options.event.clearAllColumns();
                    $.clearClientCache();
                }
                p.wait(false, action);
            }, null, function () {
                p.wait(false, action);
            })
          }
          q._close();
      });
      break;
    default:
      break;
  }
}
filter$analysisSalesData.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;
  switch (cF){
    case 'data_analysis_struct':
      if (v != "") {
        p.request('GET', '', [['id', 'I', v], ['controller', 'C', p.options.controller]], function(pp, d){
          d = new DataRow(d);
          p.options._pivotInfo = d.val('pivotinfo');
          p.options.event.clearAllColumns();
          if (p.options._admin == 1) p.valForm('form_type', d.val('form_type'));
          filter$analysisLoadPivot(p, p.options._pivotInfo);
        })

      }else {
        this.clearAllColumns();
      }
      break;
    default:
      break;
  }
}
filter$analysisSalesData.prototype.clearAllColumns = function (){
  this.commandActionClick('btn_deleteall_rows');
  this.commandActionClick('btn_deleteall_columns');
  this.commandActionClick('btn_deleteall_pivots');
}
function filter$analysisLoadPivot(p, cPivotInfo) {
  var i, v, fis = p.options.fis, o = p.jObject('data_analysis_struct'), lst = p.jObject('data_struct').list('instance'), lstRows = p.jObject('data_rows').list('instance'), lstColumns = p.jObject('data_columns').list('instance'), lstPivot = p.jObject('data_pivot').list('instance')
    , ap = cPivotInfo.split('|'), rows = ap[1].split(','), cols = ap[2].split(','), vals = ap[3].split(','), opr = [], headers = ap[4].split(',');
  if (ap[5] == "")
    p.options.pivotGroups = [];
  else
    p.options.pivotGroups = ap[5].split(',');
  var k = vals.length;
  while (k--) {
    opr[k] = vals[k].substr(1, vals[k].indexOf("-") - 1);
    vals[k] = vals[k].substr(vals[k].indexOf("-") + 1);
  }
  for (i = 0; i < rows.length; i++) {
    if (fis[rows[i]] && fis[rows[i]].right) {
      lst.val([rows[i]]);
      filter$analysis$TransferColumns(p, lst, lstRows, false);
    }
  }

  for (i = 0; i < headers.length; i++) {
    v = cols[i];
    if (fis[v] && fis[v].right) {
      lst.val([v]);
      filter$analysis$TransferColumns(p, lst, lstColumns, false);
      if (fis[headers[i]].right) {
        lstColumns.items(v).attr('view', headers[i]);
        if (headers[i] != v) {
            lstColumns.items(v).setListItemText(fis[v].text.lan + ' (' + fis[headers[i]].text.lan + ')', lstColumns);
        }
      } else lstColumns.items(v).attr('view', v);
    }
  }

  for (i = 0; i < vals.length; i++) {
    v = vals[i];
    if (fis[v] && fis[v].right) {
      lst.val([v]);
      filter$analysis$TransferColumns(p, lst, lstPivot, false);
      lstPivot.items(v).attr("xtype", opr[i]);
    }
  }

  p.valForm('name', o.find('option:selected').text());
  filter$analysis$MenuTextInRow(p, lstRows.jItems());
  filter$analysis$MenuTextInColumn(p, lstColumns.jItems());
  filter$analysis$MenuTextInPivot(p, lstPivot.jItems());
  filter$analysis$RefreshGroupInRow(p);
}
function filter$analysisSalesData$Saved(p, id){
  var o = p.jObject('data_analysis_struct');
  if (p.options._filterAction == 'NEW') {
    o.append("<" + "option value='" + id + "'>" + p.valForm('name') + "</option>");
    o.fval(id);
  }
  else o.find("[value='" + id + "']").text(p.valForm('name')).attr('value', id);
}
         &PivotScript;

css.text:

.btn_add_rows, .btn_remove_rows, .btn_moveup_rows, .btn_movedown_rows{
  margin-left: 40px;
  margin-top: 5px;
  height: 40px;
}
.btn_add_rows > div, .btn_remove_rows > div, .btn_moveup_rows > div, .btn_movedown_rows > div{
  background: url(../Images/all_icon_1.png);
  width: 16px;
  height: 16px;
  margin-top: 7px;
  margin-left: 13px;
}
.data_struct_label > div, .data_rows_label > div, .data_columns_label > div, .data_pivot_label > div{
  background: url(../Images/all_icon_1.png);
  width: 16px;
  height: 16px;
  display: inline-block;
  margin-right: 5px;
  margin-bottom: 5px;
  margin-left: 5px;
  vertical-align: middle;
}

.btn_add_rows > div{
  background-position: -144px -464px !important;
}
.btn_remove_rows > div{
  background-position: -112px -464px !important;
}
.btn_moveup_rows > div{
  background-position: -160px -464px !important;
}
.btn_movedown_rows > div{
  background-position: -128px -464px !important;
}
.data_struct_label > div{
  background-position: -128px -464px !important;
}
.data_struct_label > div{
  background-position: -448px -448px !important;
}
.data_rows_label > div{
  background-position: -16px -464px !important;
}
.data_columns_label > div{
  background-position: -96px -464px !important;
}
.data_pivot_label > div{
  background-position: -32px -464px !important;
}

.btn_add_rows{
  margin-top: 50px;
}
.btn_moveup_rows{
  margin-top: 30px;
}

.data_struct_label, .data_rows_label, .data_columns_label, .data_pivot_label{
  width: 100%;
  height: 30px;
  border: 1px solid #ddd;
  border-bottom: none;
  margin-top: 10px;
  background: #f6f6f9;
  border-top-left-radius: 5px;
  border-top-right-radius: 5px;
  color: #549bd0 !important;
  display: block;
}
#DIR_analysisSalesData_Filter .data_struct, .data_rows, .data_columns, .data_pivot{
  margin-bottom: 0px;
} 


.item-drag-view{
	height: 25px;
	position: fixed;
	z-index: 9999;
	background: #f5f299;
	opacity: 0.9;
	padding-left: 5px;
	padding-right: 5px;
	padding-top: 5px;
	padding-bottom: 5px;
	cursor: default;
	display: inline-flex;
  visibility: hidden;
	color: #549bd0;
}
.item-drag-view-icon{
	width: 0px;
	height: 0px;
	display: initial;
  background: url(../Images/all_icon_1.png);
}
.icon-drag-view-disable{
	width: 16px;
	height: 16px;
	background-position: -176px -464px;
}
.item-drag-view-text{
	display: inline;
	top: -1px;
  position: relative;
	padding-left: 5px;
	padding-right: 5px;
}

.item-drop-view{
	background: #4684e2 !important;
  border: none !important;
  padding: 1px !important;
}
.item-drop-mask{
	background: transparent !important;
  border: none !important;
	height: 10px;
}
.item-hidden{
  visibility: hidden;
}

.list-icon-left{
  width: 16px;
  height: 16px;
  float: left;
  margin-right: 5px;
  display: none;
  pointer-events: none;
}
.list-icon-right{
  width: 20px;
  height: 20px;
  float: right; 
  cursor: pointer;
  margin-top: -18px;
  margin-right: -4px;
  border: 1px solid transparent;
  display: none;
}

.list-icon-right > span{
  border: solid black;
  border-width: 0 1px 1px 0;
  padding: 3px;
  margin-top: 5px;
  margin-right: 6px;
  transform: rotate(45deg);
  -webkit-transform: rotate(45deg);
  display: inline-block;
  float: right;
}
.list-icon-right:hover span {
  border: solid #549bd0;
  border-width: 0 1px 1px 0;
}
.list-icon-right:hover {
  border: 1px solid #549bd0;
}

.list-item-group{
  border: none !important;
  padding-left: 2px !important;
}
.list-item-group[expand="0"] > .list-icon-left { 
  display: block;  
  margin-top: 2px;
  width: 2px; 
  height: 10px; 
  border-top: 6px solid transparent;
  border-bottom: 6px solid transparent;
  border-left: 6px solid #549bd0;
}
.list-item-group[expand="1"] > .list-icon-left { 
  display: block;  
  margin-top: 6px;
  width: 2px; 
  height: 10px; 
  border-left: 6px solid transparent;
  border-right: 6px solid transparent;
  border-top: 6px solid #549bd0;
}
.data_struct > li:not([group="#"]) > .list-icon-left { 
  display: block;  
  width: 3px;
  height: 3px;
  background: #549bd0;
  border-radius: 100%;
  margin-top: 7px;
}
.data_struct > li[group=""] > .list-icon-left, .list-group > li[group="#"] > .list-icon-right{ 
  display: none;
}

.list-item-group:hover{
  background: none !important;
  color: #549bd0;
  cursor: pointer;
}
.list-group .list-text{
  pointer-events: none;
  white-space: nowrap;
  text-overflow: ellipsis;
  overflow: hidden;
  margin-right: 20px;
}

.list-group:focus{
  box-shadow: 3px 3px 10px #888888;
}

.list-group > li > .list-icon-right{
  display: block;
}
